import { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import Button from '../components/Button';

export default function QuizPage() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const domain = searchParams.get('domain') || 'web-development';
  
  const [questions, setQuestions] = useState([]);
  const [selected, setSelected] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [loading, setLoading] = useState(false);
  const [difficulty, setDifficulty] = useState(null); // New state for difficulty

  const fetchQuestions = async (level) => {
    setLoading(true);
    setDifficulty(level);
    try {
      const res = await fetch("http://localhost:5000/api/quiz/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ domain, difficulty: level })
      });
      const data = await res.json();
      setQuestions(data);
    } catch (err) {
      console.error("Fetch Error:", err);
    } finally {
      setLoading(false);
    }
  };

  const cleanStr = (str) => str ? str.replace(/^[a-z0-9][\s).:-]+/i, "").trim().toLowerCase() : "";

  const score = questions.reduce((acc, q, idx) => {
    const userAns = cleanStr(selected[idx]);
    const correctAns = cleanStr(q.answer);
    return acc + (userAns === correctAns ? 1 : 0);
  }, 0);

  // 1. Level Selection UI
  if (!difficulty && !loading) {
    return (
      <div className="max-w-2xl mx-auto p-10 text-center space-y-8 bg-white rounded-[2rem] border shadow-sm mt-10">
        <h2 className="text-3xl font-bold">Select Difficulty</h2>
        <p className="text-slate-500">Choose your challenge level for {domain.replace(/-/g, ' ')}</p>
        <div className="grid gap-4">
          {['Easy', 'Medium', 'Hard'].map((level) => (
            <button
              key={level}
              onClick={() => fetchQuestions(level.toLowerCase())}
              className="p-5 text-xl font-semibold border-2 rounded-2xl hover:border-blue-500 hover:bg-blue-50 transition-all capitalize"
            >
              {level}
            </button>
          ))}
        </div>
      </div>
    );
  }

  if (loading) return (
    <div className="flex flex-col items-center justify-center p-20 space-y-4">
      <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
      <p className="text-slate-600 font-medium">AI is generating 10 {difficulty} questions...</p>
    </div>
  );

  return (
    <div className="max-w-4xl mx-auto p-4 space-y-6">
      <div className="bg-white rounded-3xl p-8 border shadow-sm">
        <div className="flex justify-between items-center mb-8">
          <h2 className="text-2xl font-bold capitalize">{domain.replace(/-/g, ' ')} ({difficulty})</h2>
          <span className="px-4 py-1 bg-slate-100 rounded-full text-sm font-bold">10 Questions</span>
        </div>
        
        <div className="space-y-8">
          {questions.map((q, idx) => (
            <div key={idx} className="p-6 rounded-2xl bg-slate-50 border">
              <p className="font-semibold text-lg mb-4">{idx + 1}. {q.question}</p>
              <div className="grid gap-3 sm:grid-cols-2">
                {q.options.map((opt) => {
                  const isCorrect = submitted && cleanStr(opt) === cleanStr(q.answer);
                  const isSelected = selected[idx] === opt;
                  return (
                    <button
                      key={opt}
                      disabled={submitted}
                      onClick={() => setSelected(prev => ({ ...prev, [idx]: opt }))}
                      className={`p-4 text-left border rounded-xl transition-all ${
                        isSelected ? 'bg-blue-600 text-white border-blue-600' : 'bg-white hover:border-blue-300'
                      } ${isCorrect ? 'ring-4 ring-green-400 bg-green-50 text-green-900 border-green-500' : ''}`}
                    >
                      {opt}
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
        </div>

        <div className="mt-8 border-t pt-6">
          {!submitted ? (
            <Button onClick={() => setSubmitted(true)} disabled={Object.keys(selected).length < questions.length}>
              Submit Quiz
            </Button>
          ) : (
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
              <div className="text-3xl font-bold text-teal-600">Score: {score} / 10</div>
              <Button onClick={() => navigate(`/roadmap/${domain}`)}>Generate Roadmap →</Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
